// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        value = bound(value, 1, type(uint128).max);
        vm.deal(address(this), value);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("deposit()"));
        assertTrue(success, "deposit should not revert");
    }
}

